css:
.md-body {
  --font-body: Georgia, "Songti SC", serif;
  --c-surface:#f7f4fa; --c-text:#3a3340; --c-heading:#2c2640; --c-accent:#6b4f8a; --c-line:#e3dcec;
  --c-quote-bg:#efeaf5; --c-code-bg:#efeaf5; --c-table-head:#efeaf5; --c-muted:#8a7f95;
  --fs-body:16px; --lh-body:1.9; --space-h:2.2em 0 .9em; --radius:8px;
}
.md-body h1{letter-spacing:.04em; border-bottom:2px solid #6b4f8a; padding-bottom:.4em}
.md-body h2{color:#6b4f8a}
.md-body blockquote{border-left:3px solid #6b4f8a; background:#efeaf5}
.md-body a{color:#6b4f8a}
